// BROKEN: equals without hashCode
class User {
    String email;
    @Override public boolean equals(Object o) {
        if (!(o instanceof User)) return false;
        return email.equals(((User) o).email);
    }
    // hashCode() inherited from Object -> identity-based
}
// new HashSet<>(); add(u1); add(u2 with same email);
// Both stored because they hash to different buckets

// CORRECT
class User {
    String email;
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        return Objects.equals(email, ((User) o).email);
    }
    @Override public int hashCode() {
        return Objects.hash(email);
    }
}

// MODERN (Java 16+)
record User(String email) {}
// equals and hashCode auto-generated from components

// Lifecycle
NEW --> RUNNABLE --> BLOCKED (waiting for monitor) --> RUNNABLE
              \--> WAITING / TIMED_WAITING --> RUNNABLE
              \--> TERMINATED

// start() vs run() -- the classic trap
Thread t = new Thread(() ->
    System.out.println(Thread.currentThread().getName()));
t.run();    // prints "main" -- runs on caller thread, NO new thread
t.start();  // prints "Thread-0" -- spawns an actual new thread

// Runnable vs Callable
Runnable r = () -> doWork();                    // no return
Callable<Integer> c = () -> computeResult();    // returns Integer

// Daemon thread
Thread bg = new Thread(() -> cleanupLoop());
bg.setDaemon(true); // JVM will not wait for this on exit
bg.start();

// Correct: bounded queue + explicit rejection + named threads
ThreadPoolExecutor pool = new ThreadPoolExecutor(
    10,                                   // corePoolSize
    50,                                   // maximumPoolSize
    60, TimeUnit.SECONDS,                 // keepAliveTime
    new ArrayBlockingQueue<>(1000),       // bounded workQueue
    r -> { Thread t = new Thread(r, "api-worker"); return t; },
    new ThreadPoolExecutor.CallerRunsPolicy()  // backpressure to caller
);

// TRAP: unbounded queue -- maximumPoolSize never triggers
Executors.newFixedThreadPool(10);  // LinkedBlockingQueue with Integer.MAX_VALUE

// Graceful shutdown
pool.shutdown();                          // stop accepting, drain queue
if (!pool.awaitTermination(30, TimeUnit.SECONDS))
    pool.shutdownNow();                   // interrupt + drop queue

// Java 21+ virtual threads (IO-bound workloads)
try (ExecutorService v = Executors.newVirtualThreadPerTaskExecutor()) {
    v.submit(() -> callRemoteService());
}

// Parallel fan-out: user + orders + recommendations
CompletableFuture<User> uF = CompletableFuture.supplyAsync(
    () -> userService.get(id), pool);
CompletableFuture<List<Order>> oF = CompletableFuture.supplyAsync(
    () -> orderService.byUser(id), pool);
CompletableFuture<List<Rec>> rF = CompletableFuture.supplyAsync(
    () -> recService.forUser(id), pool);

CompletableFuture<Page> pageF = uF
    .thenCombine(oF, UserWithOrders::new)
    .thenCombine(rF, Page::new)
    .exceptionally(ex -> Page.fallback(id));   // MUST attach to avoid swallow

Page page = pageF.join();                       // unchecked wait

// Java 9+: deadline
pageF.orTimeout(500, TimeUnit.MILLISECONDS);

// Which thread runs the function?
// thenApply     -> completing thread (unpredictable)
// thenApplyAsync -> pool thread (predictable)

// Comparable: canonical ordering inside the class
class User implements Comparable<User> {
    String name; int age;
    @Override public int compareTo(User o) {
        return Integer.compare(this.age, o.age);   // NOT this.age - o.age
    }
}

// Comparator: external, chainable, reusable
Comparator<User> byAgeThenName = Comparator
    .comparingInt(User::getAge)
    .thenComparing(User::getName)
    .reversed();

users.sort(byAgeThenName);

// Overflow trap
Comparator<Integer> broken = (a, b) -> a - b;   // breaks near Integer.MIN/MAX
Comparator<Integer> fixed  = Integer::compare;

// TreeSet uses compareTo, NOT equals
// class User compareTo -> by email, equals -> by id
// Two users with same email, different ids -> second silently NOT added

// == vs equals
String a = "hello";              // interned in pool
String b = "hello";              // same pooled object
String c = new String("hello");  // fresh heap object, contents equal

a == b;      // true  (same pooled instance)
a == c;      // false (different objects)
a.equals(c); // true  (content comparison)
c.intern() == a;  // true (forced to canonical)

