// Custom BeanFactoryPostProcessor -- modify BeanDefinitions (recipes)
@Component
static class MyBfpp implements BeanFactoryPostProcessor {
    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory bf) {
        BeanDefinition bd = bf.getBeanDefinition("someBean");
        bd.getPropertyValues().add("timeout", 5000);
        // bean itself has not been instantiated yet
    }
