// Custom BeanPostProcessor -- wrap every bean after init
@Component
static class TimingBpp implements BeanPostProcessor {
    @Override
    public Object postProcessBeforeInitialization(Object bean, String name) {
        return bean;                          // @PostConstruct discoverers run here
    }
    @Override
    public Object postProcessAfterInitialization(Object bean, String name) {
        if (bean instanceof TimedApi) {
            return Proxy.newProxyInstance(   // whatever you return becomes the bean
                bean.getClass().getClassLoader(),
                bean.getClass().getInterfaces(),
                new TimingHandler(bean));
        }
        return bean;
    }
}

